-- Optional demo data. Run only for testing.
insert into public."TblP132NewsSource"("SourceName","FeedURL","WebsiteURL","DefaultCategory") values('P132 Demo','https://example.invalid/p132-demo-rss','https://example.invalid','demo') on conflict("FeedURL") do nothing;
with s as(select "SourceID" from public."TblP132NewsSource" where "FeedURL"='https://example.invalid/p132-demo-rss') insert into public."TblP132Article"("SourceID","ExternalID","Title","Summary","ContentText","OriginalURL","PublishedAt","Category") select "SourceID",'demo-001','能源政策與企業投資','台灣政府公布新的能源政策。','台灣政府今天公布新的能源政策，希望鼓勵企業投資再生能源。','https://example.invalid/demo-001',now(),'demo' from s on conflict("SourceID","ExternalID") do nothing;
insert into public."TblP132VocabularyConcept"("CanonicalZh","MeaningZh","PartOfSpeech","Domain") select '政策','政府或組織為達成目標所採取的方針或原則','noun','public affairs' where not exists(select 1 from public."TblP132VocabularyConcept" where "CanonicalZh"='政策' and "MeaningZh" like '政府或組織%');
with c as(select "ConceptID" from public."TblP132VocabularyConcept" where "CanonicalZh"='政策' order by "ConceptID" limit 1) insert into public."TblP132VocabularyForm"("ConceptID","LanguageCode","SurfaceForm","Lemma","Reading","IsPreferred") select "ConceptID",v.lang,v.form,v.lemma,v.reading,true from c cross join (values('en','policy','policy',null),('ja','政策','政策','せいさく')) v(lang,form,lemma,reading) where not exists(select 1 from public."TblP132VocabularyForm" f where f."ConceptID"=c."ConceptID" and f."LanguageCode"=v.lang and f."SurfaceForm"=v.form);
-- Offset is zero-based, EndOffset exclusive. In demo text 政策 starts at character 13 and ends at 15.
with a as(select "ArticleID" from public."TblP132Article" where "ExternalID"='demo-001'),c as(select "ConceptID" from public."TblP132VocabularyConcept" where "CanonicalZh"='政策' order by "ConceptID" limit 1) insert into public."TblP132ArticleOccurrence"("ArticleID","ConceptID","OriginalText","StartOffset","EndOffset","SentenceIndex","ContextText","MatchConfidence") select a."ArticleID",c."ConceptID",'政策',13,15,1,'台灣政府今天公布新的能源政策',1 from a,c on conflict("ArticleID","StartOffset","EndOffset") do nothing;
